{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "A glucose-bearing compound crossed the BBB in rats with a brain concentration of 3.1 nmol/g, likely via GLUT1-mediated transport; the query also contains a glucosyl moiety, supporting meaningful CNS access despite the polar sugar.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A complex triterpenoid saponin reached 248.7 ng/g in rat brain after systemic dosing, demonstrating that glycosylated terpenoids can achieve measurable CNS exposure; the query is smaller and more lipophilic, so it is likely at least comparable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Ginsenoside Rh3, a glycosylated terpenoid, accumulated to 520 ng/g in rat hippocampus after oral administration, supporting CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Epimedin B, a heavily glycosylated polyphenol, hardly crossed the BBB, showing that not all glycosides penetrate; however, its much larger polar surface and multiple sugar units make it less transferable to the smaller, more lipophilic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: despite moderate passive BBB properties and an efflux-transporter risk, direct evidence from glycosylated terpenoid and glucose-bearing analogues shows measurable brain exposure; the query's smaller size, lower TPSA, and higher lipophilicity relative to those analogues support meaningful CNS access.",
  "evidence_gaps": [
    "No direct BBB data are available for the query molecule.",
    "Morgan similarities to the evidence molecules are low, limiting quantitative transferability.",
    "The aldehyde group may be a metabolic liability, and its effect on in vivo brain exposure is unknown.",
    "Exact efflux-transporter substrate status of the query is speculative."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

